import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BIMNh-ez.js";var i=JSON.parse(`{"title":"Vetoable actions run as intent, guard, compute and commit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Vetoable actions run as intent, guard, compute and commit"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.github.io/JSPrismarine/adr/0013-vetoable-actions-are-staged"}],["link",{"rel":"canonical","href":"https://jsprismarine.github.io/JSPrismarine/adr/0013-vetoable-actions-are-staged"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0013-vetoable-actions-are-staged.md"}},"headers":[],"relativePath":"adr/0013-vetoable-actions-are-staged.md","filePath":"adr/0013-vetoable-actions-are-staged.md","lastUpdated":1794388700000}`),a={name:`adr/0013-vetoable-actions-are-staged.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="vetoable-actions-run-as-intent-guard-compute-and-commit" tabindex="-1">Vetoable actions run as intent, guard, compute and commit <a class="header-anchor" href="#vetoable-actions-run-as-intent-guard-compute-and-commit" aria-label="Permalink to “Vetoable actions run as intent, guard, compute and commit”">​</a></h1><p>Status: accepted</p><p>Every action that can be vetoed or modified runs in four stages.</p><ol><li>The intent is plain data that describes the attempt.</li><li>The guard stage runs cheap synchronous checks in a stated order: pack-defined rules such as <code>damage_sensor</code> and <code>cannot_be_attacked</code>, game rules, permissions, and then scripting before-hooks. A guard reads the intent and returns one of three results: pass, veto, or replacement values for parameters the pipeline declares replaceable, such as a damage amount, an effect duration, a target game mode, an explosion&#39;s block list or an item stack. A guard never writes state. Later guards see the replaced intent. The first veto stops everything after it, so nothing is computed and nothing is logged except a rejection record.</li><li>The compute stage does the expensive work, such as damage, loot rolls and explosion rays, and only after the guards pass. A change to a result is a declared modifier with an operation, a value and a priority, as Java&#39;s attribute modifiers have, and never a listener mutating a shared object.</li><li>The commit stage applies the result through the setters and appends the deltas to the change log (<a href="/JSPrismarine/pr-preview/pr-2948/adr/0012-the-change-log-is-the-history.html">ADR 0012</a>). After commit nothing can veto, and observers read the log.</li></ol><p>Offloaded or long-running work carries a request id and a cancellation token that it checks at checkpoints. A result for a cancelled request is dropped when it is admitted (<a href="/JSPrismarine/pr-preview/pr-2948/adr/0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>).</p><p>The legacy cancellable events set a flag that the raising code reads once. Listener order follows <code>Set</code> insertion, an async listener&#39;s cancel after its first <code>await</code> is lost, and the emit site decides whether listeners are awaited at all. A veto that arrives late throws away finished work. With cheap guards first, a veto costs one check.</p><p>Replacement exists because the Bedrock Script API needs it. In <code>@minecraft/server</code> 2.11.0, ten of the seventeen stable before-events let a script rewrite a parameter of the action, for example <code>EntityHurtBeforeEvent.damage</code>, <code>EffectAddBeforeEvent.duration</code> and <code>ExplosionBeforeEvent.setImpactedBlocks</code>, and one custom component hook rewrites a parameter without being able to cancel. The same documentation runs before-event callbacks in restricted execution, where a write to world state throws. A guard that returns replacements and writes nothing matches both rules.</p><p>This replaces the legacy cancellable event objects for simulation actions. Each pipeline defines its own guard list and modifier slots.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};